import std.concurrent as conc
import std.time

test "tied" {
    let ch: conc.Channel<Int64> = conc.channel(0)
    scope {
        let a = task effect net time {
            let _ = time.sleep(10)
            ch.send(1)
        }
        let b = task effect net time {
            let _ = time.sleep(10)
            ch.send(2)
        }
        advanceTime(10)
        let _ = ch.receive()
        let _ = ch.receive()
        let _ = a.await()
        let _ = b.await()
    }
    assert(true, "done")
}

